const flowConfig=(project='Steer')=>({name:`${project} · MR 自动审查`,project,description:'MR 创建或更新后，自动审查并更新 Codebase 汇总评论。',target:'main, release/*',events:['created','updated'],reviewer:'Code Reviewer',model:'GPT-5.4',effort:'high',skills:['general','go','architecture'],latest:true,ruleVersion:'1.4',reply:true,build:true,test:true});
const freshMaintenance=()=>({tab:'flows',filter:'all',search:'',ruleFilter:'all',ruleSearch:'',active:'steer',editing:null,flowDraft:null,ruleEditing:'general',executing:null,flows:[{id:'steer',published:flowConfig(),draft:null,version:3,enabled:true,last:'今天 14:28',lastResult:'需要处理'},{id:'relay',published:flowConfig('Relay'),draft:null,version:2,enabled:true,last:'今天 11:46',lastResult:'证据不足'}],rules:[{id:'general',name:'通用代码审查',category:'通用规范',source:'steer',version:'1.4',content:defaultRule,draft:null,history:['1.4','1.3']},{id:'go',name:'Go 并发与资源释放',category:'语言规范',source:'steer',version:'2.1',content:'# Go 并发与资源释放\n\n检查 context 是否贯穿取消与锁等待。\n检查 goroutine 退出、资源释放和共享状态。\n确认 race 检查覆盖关键并发路径。',draft:null,history:['2.1','2.0']},{id:'architecture',name:'项目架构与兼容性',category:'项目规范',source:'repo',version:'1.2',content:'# 项目架构与兼容性\n\n检查 API 与 SDK 版本兼容。\n检查数据库迁移与滚动部署顺序。\n独立构建使用已发布依赖，不能依赖本地 go.work。',draft:null,history:['1.2','1.1']}],runs:[{id:'184',flow:'steer',flowVersion:3,ruleVersion:'1.4',title:'飞书默认项目与回复方式配置',head:'98c7c2f',result:'需要处理',writeback:'sent',time:'今天 14:28',model:'GPT-5.4',effort:'high'},{id:'183',flow:'relay',flowVersion:2,ruleVersion:'1.4',title:'准备工作区期间持续续租',head:'20fe146',result:'证据不足',writeback:'sent',time:'今天 11:46',model:'GPT-5.4',effort:'high'},{id:'181',flow:'steer',flowVersion:3,ruleVersion:'1.4',title:'精简会话导航与归档入口',head:'b5a2a6b',result:'无阻断问题',writeback:'sent',time:'昨天 15:08',model:'GPT-5.4',effort:'high'}]});
let maintenance;try{maintenance=JSON.parse(localStorage.getItem('steer-review-maintenance-v2'))||freshMaintenance()}catch{maintenance=freshMaintenance()}
const clone=obj=>JSON.parse(JSON.stringify(obj));
const currentFlow=()=>maintenance.flows.find(f=>f.id===maintenance.active)||maintenance.flows[0];
const currentRule=()=>maintenance.rules.find(r=>r.id===maintenance.ruleEditing)||maintenance.rules[0];
const saveMaintenance=()=>localStorage.setItem('steer-review-maintenance-v2',JSON.stringify(maintenance));
state.view='home';state.running=false;state.version=maintenance.rules[0].version;state.rule=maintenance.rules[0].content;
const baseReset=prototype.reset;
prototype.reset=()=>{maintenance=freshMaintenance();baseReset();state.view='home';state.version='1.4';render()};
const cTabs=()=>`<div class="tabs" role="tablist" aria-label="自动化管理">${[['flows','流程',maintenance.flows.length],['rules','审查规则',maintenance.rules.length],['runs','运行记录',null]].map(([id,n,count])=>`<button class="tab ${maintenance.tab===id?'active':''}" role="tab" aria-selected="${maintenance.tab===id}" data-action="c-tab" data-value="${id}">${n}${count===null?'':` <span class="muted">· ${count}</span>`}</button>`).join('')}</div>`;
sidebar=function(){return `<aside class="sidebar"><div class="native-brand"><span class="brandmark">S</span><div><strong>Steer</strong><small>研发工作区</small></div>${icon('down',true)}</div><nav class="nav-section" aria-label="工作区导航"><button class="nav-item" data-action="c-context">${icon('clock')}会话</button><button class="nav-item" data-action="c-context">${icon('folder')}项目</button><button class="nav-item" data-action="c-context">${icon('bot')}智能体</button><button class="nav-item" data-action="c-tab" data-value="rules">${icon('code')}Skills</button><button class="nav-item active" data-action="c-tab" data-value="flows">${icon('branch')}自动化</button></nav><div class="nav-section"><span class="nav-label">项目</span>${['Steer','Relay'].map(p=>`<button class="nav-item" data-action="c-project-filter" data-value="${p}">${icon('folder')}${p}</button>`).join('')}</div><div class="sidebar-bottom"><button class="nav-item full" data-action="connection">${icon('plug')}设置与集成</button><div class="flex space-16"><span class="avatar">KD</span><span>kongdefei</span></div></div></aside>`};
render=function(){if(maintenance.executing&&!state.running){const pending=maintenance.executing,flow=maintenance.flows.find(f=>f.id===pending.flow);maintenance.runs.unshift({...pending,result:'需要处理',writeback:state.writeback,time:'刚刚'});if(flow){flow.last='刚刚';flow.lastResult='需要处理'}maintenance.executing=null}
 persist();saveMaintenance();$('#app').innerHTML=`<a class="skip" href="#main">跳转到内容</a><header class="prototype-bar"><div class="prototype-left"><a class="title-4" href="index.html">${icon('back',true)} 三方案对比</a>${tag('C · 修订版')}<span class="caption-5 muted">流程与规则维护 · 模拟数据</span></div><div class="actions"><a href="flow.html?concept=c" class="btn ghost small">完整流程图</a>${btn('重置原型','c-reset','ghost small')}</div></header><div class="shell">${sidebar()}<main class="main" id="main"><header class="topline"><div class="crumb"><span>研发工作区</span><span>/</span><strong>自动化</strong>${maintenance.editing?`<span>/</span><strong>${esc(maintenance.flowDraft.name)}</strong>`:''}</div><div class="actions">${btn('模拟事件','c-events','ghost small')}</div></header>${maintenanceContent()}</main></div><div id="modal-root"></div><div id="toast"></div>`;if(modal)renderModal()};
function maintenanceContent(){if(state.view==='report')return `<div class="page maintenance"><div class="audit-header">${btn(`${icon('back',true)} 返回运行记录`,'c-tab','ghost small','data-value="runs"')}<span>核实视图 · 讨论与合并仍在 Codebase</span></div>${report()}</div>`;if(maintenance.editing)return editor();return `<div class="page maintenance">${heading('自动化','维护流程与审查规则；任务自动执行，运行记录用于追踪与核实。',maintenance.tab==='flows'?btn(`${icon('plus',true)} 新建流程`,'c-new-flow','primary'):maintenance.tab==='rules'?btn(`${icon('plus',true)} 新建规则`,'c-new-rule','primary'):'')}${cTabs()}${maintenance.tab==='flows'?flowList():maintenance.tab==='rules'?ruleLibrary():runList()}</div>`}
function flowList(){const flows=maintenance.flows.filter(f=>{const c=f.draft||f.published;return (maintenance.filter==='all'||maintenance.filter==='enabled'&&f.enabled||maintenance.filter==='paused'&&!f.enabled&&f.version>0||maintenance.filter==='draft'&&f.draft)&&`${c.name} ${c.project}`.toLowerCase().includes(maintenance.search.toLowerCase())});return `<div class="maintenance-toolbar flow-toolbar"><div class="toolbar-left"><input class="search" id="flow-search" aria-label="搜索流程" placeholder="搜索流程或项目…" value="${esc(maintenance.search)}"><div class="filter-group">${[['all','全部'],['enabled','已启用'],['paused','已暂停'],['draft','有草稿']].map(([v,n])=>`<button class="filter ${maintenance.filter===v?'active':''}" data-action="c-filter" data-value="${v}">${n}</button>`).join('')}</div></div><div class="connection-inline"><span class="dot" style="color:${state.connected?'#27845a':'#b3434d'}"></span><span>Codebase ${state.connected?'已连接':'连接失效'}</span>${btn('管理连接','connection','link small')}</div></div><div class="flow-table"><div class="flow-table-header"><span>流程 / 项目</span><span>触发方式</span><span>发布版本</span><span class="last-run">最近运行</span><span></span></div>${flows.map(f=>{const c=f.version?f.published:f.draft;return `<article class="flow-table-row"><div class="flow-title">${icon('branch')}<div><div class="flow-name-line"><h3><button data-action="c-edit-flow" data-id="${f.id}">${esc(c.name)}</button></h3>${tag(f.version===0?'未发布':f.enabled?'已启用':'已暂停',f.enabled?'green':'')}${f.draft?tag('有草稿','amber'):''}</div><p>${c.project} · KDF5000 / ${c.project.toLowerCase()}</p></div></div><div class="flow-cell trigger-cell">${c.events.map(e=>e==='created'?'创建':'新提交').join(' / ')}</div><div class="flow-cell version-cell">${f.version?`<strong>v${f.version}</strong>`:'—'}<br><span class="muted">${c.skills.length} 个 Skill</span></div><div class="flow-cell last-run">${f.last}<br><span class="muted">${f.lastResult}</span></div><div class="flow-actions">${btn('编辑','c-edit-flow','ghost small',`data-id="${f.id}"`)}<details class="native-menu"><summary aria-label="${esc(c.name)}更多操作">···</summary><div class="menu-popup">${f.version?`<button data-action="c-toggle-flow" data-id="${f.id}">${f.enabled?'暂停流程':'启用流程'}</button>`:''}<button data-action="c-flow-runs" data-id="${f.id}">查看运行记录</button><button data-action="c-test-flow" data-id="${f.id}" ${f.version===0?'disabled':''}>测试已发布流程</button></div></details></div></article>`}).join('')||`<div class="empty"><h3>没有匹配的流程</h3>${btn('清除筛选','c-clear-filter','small')}</div>`}</div><div class="minor-footer"><span>Codebase 事件自动触发，不需要手动启动每次审查。</span><span>草稿不会影响已发布流程。</span></div>`}
function ruleLibrary(){const rules=maintenance.rules.filter(r=>(maintenance.ruleFilter==='all'||r.source===maintenance.ruleFilter||maintenance.ruleFilter==='draft'&&r.draft)&&r.name.includes(maintenance.ruleSearch));return `<div class="maintenance-toolbar"><input class="search" id="rule-search" aria-label="搜索审查规则" placeholder="搜索规范名称…" value="${esc(maintenance.ruleSearch)}"><div class="filter-group">${[['all','全部'],['steer','Steer 维护'],['repo','仓库同步'],['draft','有草稿']].map(([v,n])=>`<button class="filter ${maintenance.ruleFilter===v?'active':''}" data-action="c-rule-filter" data-value="${v}">${n}</button>`).join('')}</div></div><div class="flow-table rule-table"><div class="flow-table-header"><span>Review Skill</span><span>维护来源</span><span>已发布</span><span class="usage-cell">使用范围</span><span></span></div>${rules.map(r=>`<article class="flow-table-row"><div class="flow-title">${icon('file')}<div><h3><button data-action="c-edit-rule" data-id="${r.id}">${esc(r.name)}</button></h3><p>${r.category}</p>${r.draft?`<div class="space-16">${tag('有未发布草稿','amber')}</div>`:''}</div></div><div class="flow-cell source-cell">${r.source==='repo'?'Codebase 仓库':'Steer 维护'}<br><span class="muted">${r.source==='repo'?'main · 只读同步':'页面编辑并发布'}</span></div><div class="flow-cell version-cell"><strong>v${r.version}</strong></div><div class="flow-cell usage-cell">${maintenance.flows.filter(f=>(f.draft||f.published).skills.includes(r.id)).length} 个流程引用</div><div class="flow-actions">${btn(r.source==='repo'?'查看':'编辑','c-edit-rule','ghost small',`data-id="${r.id}"`)}</div></article>`).join('')||`<div class="empty"><h3>没有匹配的规则</h3>${btn('清除筛选','c-clear-rule-filter','small')}</div>`}</div><div class="minor-footer"><span>规则以 Skill 复用。发布版本不可变，仓库规则在 Codebase 中维护。</span><span>修改规则不会改变历史报告。</span></div>`}
const selectOptions=(values,current)=>values.map(v=>`<option ${v===current?'selected':''}>${v}</option>`).join('');
function editor(){const f=currentFlow(),d=maintenance.flowDraft;const row=(label,control)=>`<div class="editor-row"><div class="editor-label">${label}</div><div class="editor-control">${control}</div></div>`;return `<div class="page maintenance flow-editor">${btn(`${icon('back',true)} 返回流程列表`,'c-exit-editor','ghost small')}${heading(`${esc(d.name)} ${tag(f.version?`v${f.version}`:'未发布')}${f.draft?tag('有草稿','amber'):''}`,'配置 MR 触发、审查规则和结果回写。',`${btn('保存草稿','c-save-flow')}${btn(f.version?'发布修改':'发布并启用','c-publish-flow-confirm','primary')}`)}<div class="error" id="maintenance-flow-error" role="alert"></div><form id="maintenance-flow-form" class="flow-editor-form"><section class="editor-section" id="flow-basic"><h2>基本信息</h2>${row('流程名称',`<input class="editor-input" aria-label="流程名称" name="name" value="${esc(d.name)}" required>`)}${row('关联项目',`<select class="editor-input" aria-label="关联项目" name="project">${selectOptions(['Steer','Relay'],d.project)}</select>`)}${row('自动执行',f.version?`<button class="inline-switch" role="switch" aria-checked="${f.enabled}" data-action="c-toggle-flow" data-id="${f.id}"><span class="switch-track"></span>${f.enabled?'已启用，等待 MR 事件':'已暂停'}</button>`:'<span class="editor-static">首次发布后启用</span>')}${row('描述',`<details class="editor-description"><summary>${icon('down',true)}${d.description?'编辑描述':'添加描述'}<span class="caption-5 muted">选填</span></summary><textarea class="editor-input" aria-label="流程描述" name="description">${esc(d.description)}</textarea></details>`)}</section><section class="editor-section" id="flow-trigger"><h2>触发条件</h2>${row('Codebase',`<div class="editor-connection"><span class="dot" style="color:${state.connected?'#27845a':'#b3434d'}"></span><span>${state.connected?'已连接':'连接失效'}</span>${btn('管理连接','connection','link small')}</div>`)}${row('MR 事件',`<div class="editor-checks">${check('created','MR 创建','',d.events.includes('created'))}${check('updated','MR 有新提交','',d.events.includes('updated'))}</div>`)}${row('目标分支',`<input class="editor-input" aria-label="目标分支" name="target" value="${esc(d.target)}"><p class="editor-help">多个分支用逗号分隔，支持 release/*。</p>`)}</section><section class="editor-section" id="flow-reviewer"><h2>Reviewer 与规则</h2>${row('Reviewer',`<select class="editor-input" aria-label="Reviewer Agent" name="reviewer">${selectOptions(['Code Reviewer','架构审查员'],d.reviewer)}</select>`)}${row('模型 / Effort',`<div class="editor-model-pair"><select class="editor-input" aria-label="模型" name="model">${selectOptions(['GPT-5.4','Claude Sonnet 4.6'],d.model)}</select><select class="editor-input" aria-label="Effort" name="effort">${selectOptions(['medium','high','xhigh'],d.effort)}</select></div>`)}${row('审查规则',`<div class="flow-skill-list">${maintenance.rules.map(r=>`<label class="flow-skill-row"><input type="checkbox" name="skill-${r.id}" ${d.skills.includes(r.id)?'checked':''}><span class="flow-skill-name"><strong>${esc(r.name)}</strong>${r.source==='repo'?'<small>仓库同步</small>':''}</span>${tag('v'+r.version)}${btn('查看','c-edit-rule','link small',`data-id="${r.id}"`)}</label>`).join('')}</div>${btn('维护审查规则','c-rule-library','link small')}`)}${row('规则版本',`${check('latest','使用最新已发布版本','',d.latest)}<p class="editor-help">${d.latest?'每次运行固定规则版本，历史记录保留快照。':`固定通用规范 v${d.ruleVersion}，不自动跟随更新。`}</p>`)}</section><section class="editor-section" id="flow-output"><h2>检查与回写</h2>${row('必要检查',`<div class="editor-checks">${check('build','独立构建结果','',d.build)}${check('test','测试结果','',d.test)}</div><p class="editor-help">未执行的必要检查标记“证据不足”。</p>`)}${row('结果回写',`${check('reply','更新 MR 汇总评论','',d.reply)}<p class="editor-help">更新同一条评论，失败可重试。不自动批准或合并。</p>`)}</section>${f.version?`<div class="editor-test-footer">${btn('测试已发布版本','c-test-flow','ghost small',`data-id="${f.id}"`)}<span class="caption-5 muted">仅用于核实配置，日常审查由事件自动触发。</span></div>`:''}</form></div>`}
function runList(){const rows=maintenance.runs.filter(r=>!maintenance.runFilter||r.flow===maintenance.runFilter);return `<div class="audit-header"><span>${maintenance.runFilter?'当前流程 · ':''}任务自动记录，按需打开报告核实。</span>${maintenance.runFilter?btn('查看全部记录','c-clear-run-filter','link'):''}</div>${progress()}<div class="flow-table run-table"><div class="flow-table-header"><span>MR / 运行任务</span><span>执行流程</span><span>结果 / 回写</span><span>时间</span><span></span></div>${maintenance.executing?`<div class="flow-table-row"><div class="flow-title">${icon('clock')}<div><h3>MR !${maintenance.executing.id} · 正在审查</h3><p>执行版本已固定</p></div></div><span class="flow-cell">v${maintenance.executing.flowVersion}</span><span>${tag('正在执行')}</span><span class="flow-cell">刚刚</span><span></span></div>`:''}${rows.map(r=>`<article class="flow-table-row"><div class="flow-title">${icon('branch')}<div><h3><button data-action="c-open-run" data-key="${r.id}:${r.time}">MR !${r.id} · ${esc(r.title)}</button></h3><p>${r.head} · 规则 v${r.ruleVersion}</p></div></div><div class="flow-cell version-cell">${r.flow==='relay'?'Relay':'Steer'}<br>流程 v${r.flowVersion}</div><div class="flow-cell">${tag(r.result,r.result==='需要处理'?'red':r.result==='证据不足'?'amber':'green')}<br><span class="muted">${r.writeback==='sent'?'已回写 Codebase':'仅保存在 Steer'}</span></div><div class="flow-cell">${r.time}</div><div class="flow-actions">${btn('查看','c-open-run','ghost small',`data-key="${r.id}:${r.time}"`)}</div></article>`).join('')}</div><div class="table-foot">记录代码提交、流程版本与规则版本，不随后续配置修改。</div>`}
function readFlowForm(){const form=$('#maintenance-flow-form');if(!form)return true;const d=new FormData(form),draft={...maintenance.flowDraft};['name','project','description','target','reviewer','model','effort'].forEach(k=>draft[k]=String(d.get(k)).trim());draft.events=['created','updated'].filter(k=>d.has(k));draft.skills=maintenance.rules.filter(r=>d.has('skill-'+r.id)).map(r=>r.id);['latest','reply','build','test'].forEach(k=>draft[k]=d.has(k));maintenance.flowDraft=draft;const message=!draft.name?'请填写流程名称。':!draft.events.length?'至少选择一个 MR 触发事件。':!draft.skills.length?'至少绑定一个 Review Skill。':!draft.target?'请填写目标分支。':'';if(message){$('#maintenance-flow-error').textContent=message;return false}return true}
function rememberDraft(){currentFlow().draft=clone(maintenance.flowDraft);saveMaintenance()}
function selectTab(tab){maintenance.tab=tab;maintenance.editing=null;maintenance.flowDraft=null;state.view='home';render()}
function editFlow(id){maintenance.active=id;maintenance.editing=id;const f=currentFlow();maintenance.flowDraft=clone(f.draft||f.published);state.view='home';render()}
function openMaintenance(type){lastFocus=document.activeElement;modal=type;renderModal();requestAnimationFrame(()=>$('#modal-root [autofocus]')?.focus()||$('#modal-root button')?.focus())}
const incrementRule=v=>{const [major,minor]=v.split('.').map(Number);return `${major}.${minor+1}`};
const sharedRenderModal=renderModal;
renderModal=function(){if(!modal?.startsWith('c-')){sharedRenderModal();return}let html='';const f=currentFlow(),r=currentRule();
if(modal==='c-new-flow')html=frame('新建自动化流程','先创建草稿，发布后才接收 Codebase 事件。',`<form id="new-flow-form"><div class="form-grid"><label class="field full">流程名称<input name="name" placeholder="例如：Steer · MR 自动审查" autofocus></label><label class="field full">关联项目<select name="project"><option>Steer</option><option>Relay</option></select></label></div><div id="new-flow-error" class="error"></div></form>`,`<span>创建时不启用或执行任务</span><div class="actions">${btn('取消','close','ghost')}${btn('创建草稿','c-create-flow','primary')}</div>`);
if(modal==='c-publish-flow')html=frame('发布流程配置',f.version?'后续 MR 事件使用新配置，正在执行的任务保留原版本。':'发布后开启事件触发，不会立即执行测试任务。',`<div class="dl"><div class="dl-line"><span>流程</span><span>${esc(maintenance.flowDraft.name)}</span></div><div class="dl-line"><span>发布版本</span><span>v${f.version} → v${f.version+1}</span></div><div class="dl-line"><span>规则</span><span>${maintenance.flowDraft.skills.length} 个 Skill · ${maintenance.flowDraft.latest?'最新已发布版本':'固定版本'}</span></div><div class="dl-line"><span>自动执行</span><span>${f.version?(f.enabled?'保持启用':'保持暂停'):'发布后启用'}</span></div></div><div class="note">草稿与正式发布分开。历史记录不改变。</div><div id="publish-flow-error" class="error"></div>`,`<span>测试运行是单独的可选操作</span><div class="actions">${btn('继续编辑','close','ghost')}${btn('确认发布','c-publish-flow','primary')}</div>`);
if(modal==='c-rule-editor')html=frame(`Review Skill · ${esc(r.name)}`,`已发布 v${r.version} · ${r.draft?'有未发布草稿':'没有未发布修改'}`,`<div class="rule-editor-layout"><div><div class="source-row"><span class="caption-5 muted">维护来源</span><strong class="title-4">${r.source==='repo'?'Codebase 仓库':'Steer'}</strong>${r.source==='repo'?tag('只读同步'):''}</div>${r.source==='repo'?'<div class="note">来源：steer / main / review/architecture.md。在 Codebase 修改正文并走 MR。</div>':''}<label class="field space-16">规范内容<textarea id="maintenance-rule-editor" ${r.source==='repo'?'readonly':''}>${esc(r.draft||r.content)}</textarea></label><div class="error" id="maintenance-rule-error"></div></div><aside class="rule-editor-meta"><h3>使用情况</h3>${maintenance.flows.filter(f=>(f.draft||f.published).skills.includes(r.id)).map(f=>`<p class="caption-5 muted">${esc((f.draft||f.published).name)}</p>`).join('')}<div class="divider"></div><h3>已发布版本</h3><div class="rule-version-stack">${r.history.map(v=>`<div class="history-line"><span>v${v}</span>${tag(v===r.version?'当前版本':'历史版本')}</div>`).join('')}</div><div class="note space-24">MR 中未发布的规则不会覆盖正式规范。</div></aside></div>`,`<span>${r.category} · ${maintenance.flows.filter(f=>(f.draft||f.published).skills.includes(r.id)).length} 个流程引用</span><div class="actions">${btn('关闭','close','ghost')}${r.source==='repo'?btn('同步仓库版本','c-sync-rule','primary'):`${btn('保存草稿','c-save-rule')}${btn('发布版本','c-publish-rule-confirm','primary')}`}</div>`,true);
if(modal==='c-publish-rule')html=frame('发布审查规则','跟随最新规范的流程，在下次任务启动时使用新版本。',`<div class="dl"><div class="dl-line"><span>Review Skill</span><span>${esc(r.name)}</span></div><div class="dl-line"><span>版本</span><span>v${r.version} → v${incrementRule(r.version)}</span></div><div class="dl-line"><span>使用范围</span><span>${maintenance.flows.filter(f=>f.published.skills.includes(r.id)&&f.published.latest).length} 个已发布流程跟随更新</span></div></div><div class="note">每次运行固定规则快照，正在执行与历史任务不会切换版本。</div>`,`<span>发布后保留版本历史</span><div class="actions">${btn('返回编辑','c-edit-rule','ghost',`data-id="${r.id}"`)}${btn('确认发布','c-publish-rule','primary')}</div>`);
if(modal==='c-new-rule')html=frame('新建 Review Skill','独立维护，再由流程绑定。',`<form id="new-rule-form"><label class="field">规范名称<input name="name" placeholder="例如：数据库迁移检查" autofocus></label><label class="field space-16">规范内容<textarea name="content"># 数据库迁移检查\n\n检查迁移顺序、回滚路径与版本兼容。\n每条问题附代码位置和触发条件。</textarea></label><div id="new-rule-error" class="error"></div></form>`,`<span>创建草稿，不影响现有流程</span><div class="actions">${btn('取消','close','ghost')}${btn('创建草稿','c-create-rule','primary')}</div>`);
if(modal==='c-leave-editor')html=frame('返回流程列表','当前编辑内容尚未保存。','<p class="muted">可以先保存草稿，或放弃本次未保存的修改。已发布配置不受影响。</p>',`<span>已发布流程保持原样</span><div class="actions">${btn('继续编辑','close','ghost')}${btn('放弃未保存修改','c-discard-editor')}${btn('保存草稿并返回','c-save-exit','primary')}</div>`);
if(modal==='c-events')html=frame('模拟 Codebase 事件','模拟自动触发，发布配置与运行记录保持分离。',`<div class="rule-list"><button class="item-row" data-action="c-auto-event"><span class="row-icon">${icon('branch')}</span><div class="grow"><h3>收到 MR 新提交</h3><p>已启用流程自动审查，暂停流程不创建任务。</p></div>${icon('arrow',true)}</button><button class="item-row" data-action="c-duplicate-event"><span class="row-icon">${icon('refresh')}</span><div class="grow"><h3>重复收到同一个事件</h3><p>复用已有任务，不重复审查。</p></div></button><button class="item-row" data-action="scenarios"><span class="row-icon">${icon('review')}</span><div class="grow"><h3>核实报告中的异常</h3><p>查看旧报告过期、检查缺失与回写失败。</p></div></button></div>`);
if(modal==='c-context')html=frame('工作区入口','自动化复用 Steer 的项目、Agent 与 Skill 能力。',`<div class="rule-list"><div class="rule-row">${icon('folder')}<div><strong class="title-4">Steer / Relay 项目</strong><span class="muted">项目绑定仓库与 Runtime。</span></div>${btn('相关流程','c-tab','small','data-value="flows"')}</div><div class="rule-row">${icon('bot')}<div><strong class="title-4">Code Reviewer</strong><span class="muted">复用现有 Agent 与模型配置。</span></div>${btn('流程配置','c-edit-flow','small','data-id="steer"')}</div></div>`,`<span>本次原型聚焦自动化维护</span>${btn('返回','close')}`);
$('#modal-root').innerHTML=html};
function readRule(){const r=currentRule(),text=$('#maintenance-rule-editor')?.value.trim();if(!text){$('#maintenance-rule-error').textContent='审查规范不能为空。';return false}r.draft=text;saveMaintenance();return true}
function finishRulePublish(){const r=currentRule();r.versions=r.versions||{};r.versions[r.version]=r.content;r.content=r.draft||r.content;r.draft=null;r.version=incrementRule(r.version);r.history.unshift(r.version);r.versions[r.version]=r.content;if(r.id==='general'){state.version=r.version;state.rule=r.content}close();render();notice(`Review Skill v${r.version} 已发布，历史报告保持原版本。`)}
const sharedRun=run;
run=function(id=state.selected){const flow=currentFlow();if(!flow?.version){notice('请先发布流程，再测试已发布版本。');return}if(state.running){notice('已有任务正在执行。');return}const cfg=flow.published,ruleVersion=cfg.latest?maintenance.rules[0].version:cfg.ruleVersion;state.reviewer=cfg.reviewer;state.model=cfg.model;state.effort=cfg.effort;state.reply=cfg.reply;const latestVersion=state.version,latestContent=state.rule;state.version=ruleVersion;state.rule=maintenance.rules[0].versions?.[ruleVersion]||maintenance.rules[0].content;maintenance.tab='runs';maintenance.editing=null;maintenance.flowDraft=null;maintenance.runFilter=flow.id;maintenance.executing={id,flow:flow.id,flowVersion:flow.version,ruleVersion,title:id==='184'?'飞书默认项目与回复方式配置':id==='183'?'准备工作区期间持续续租':'精简会话导航与归档入口',head:state.outdated?'7a8b9c0':id==='184'?state.head:id==='183'?'20fe146':'b5a2a6b',ruleContent:state.rule,model:cfg.model,effort:cfg.effort};if(!state.connected){maintenance.executing=null;open('connection');return}sharedRun(id);state.version=latestVersion;state.rule=latestContent;saveMaintenance()};
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;if(!a.startsWith('c-'))return;e.preventDefault();e.stopImmediatePropagation();
if(a==='c-events'){openMaintenance('c-events');return}
if(a==='c-auto-event'){close();const f=currentFlow();if(!f.enabled){notice('当前流程已暂停，事件已忽略，未创建审查任务。');return}if(!f.published.events.includes('updated')){notice('当前流程未订阅 MR 新提交事件，未创建任务。');return}state.outdated=true;run('184');return}
if(a==='c-duplicate-event'){close();notice('同一事件已接收，复用已有任务，未重复执行。');return}
if(a==='c-rule-library'){readFlowForm();maintenance.nextTab='rules';if(JSON.stringify(maintenance.flowDraft)!==JSON.stringify(currentFlow().draft||currentFlow().published)){openMaintenance('c-leave-editor')}else selectTab('rules');return}
if(a==='c-reset'){prototype.reset();notice('C 方案已重置到流程维护首页。');return}
if(a==='c-tab'){close();if(maintenance.editing){readFlowForm();if(JSON.stringify(maintenance.flowDraft)!==JSON.stringify(currentFlow().draft||currentFlow().published)){maintenance.nextTab=el.dataset.value;openMaintenance('c-leave-editor');return}}selectTab(el.dataset.value);return}
if(a==='c-context'){openMaintenance('c-context');return}
if(a==='c-new-flow'){openMaintenance('c-new-flow');return}
if(a==='c-create-flow'){const d=new FormData($('#new-flow-form')),name=String(d.get('name')).trim();if(!name){$('#new-flow-error').textContent='请填写流程名称。';return}const cfg=flowConfig(d.get('project'));cfg.name=name;const id='flow-'+Date.now();maintenance.flows.push({id,published:clone(cfg),draft:clone(cfg),version:0,enabled:false,last:'尚未运行',lastResult:'—'});close();editFlow(id);notice('流程草稿已创建，尚未启用。');return}
if(a==='c-edit-flow'){if(maintenance.editing)readFlowForm();close();editFlow(el.dataset.id);return}
if(a==='c-save-flow'||a==='c-save-exit'){if(!readFlowForm())return;rememberDraft();if(a==='c-save-exit'){close();selectTab(maintenance.nextTab||'flows');maintenance.nextTab=null}else render();notice('草稿已保存，正式流程保持原配置。');return}
if(a==='c-exit-editor'){readFlowForm();if(JSON.stringify(maintenance.flowDraft)!==JSON.stringify(currentFlow().draft||currentFlow().published)){maintenance.nextTab='flows';openMaintenance('c-leave-editor')}else selectTab('flows');return}
if(a==='c-discard-editor'){close();selectTab(maintenance.nextTab||'flows');maintenance.nextTab=null;return}
if(a==='c-publish-flow-confirm'){if(!readFlowForm())return;rememberDraft();openMaintenance('c-publish-flow');return}
if(a==='c-publish-flow'){if(!state.connected){$('#publish-flow-error').textContent='Codebase 连接不可用，请验证后发布。';return}const f=currentFlow();f.published=clone(maintenance.flowDraft);f.published.ruleVersion=maintenance.rules[0].version;f.draft=null;if(!f.version)f.enabled=true;f.version++;maintenance.flowDraft=clone(f.published);close();render();notice(`流程 v${f.version} 已发布，后续事件使用新配置。`);return}
if(a==='c-toggle-flow'){const f=maintenance.flows.find(f=>f.id===el.dataset.id);if(!f.version)return;if(!f.enabled&&!state.connected){open('connection');return}if(maintenance.editing)readFlowForm();f.enabled=!f.enabled;render();notice(f.enabled?'流程已启用，等待 MR 事件。':'流程已暂停，不再接收新事件。');return}
if(a==='c-filter'){maintenance.filter=el.dataset.value;render();return}
if(a==='c-clear-filter'){maintenance.filter='all';maintenance.search='';render();return}
if(a==='c-rule-filter'){maintenance.ruleFilter=el.dataset.value;render();return}
if(a==='c-clear-rule-filter'){maintenance.ruleFilter='all';maintenance.ruleSearch='';render();return}
if(a==='c-project-filter'){maintenance.search=el.dataset.value;maintenance.filter='all';selectTab('flows');return}
if(a==='c-flow-runs'){maintenance.runFilter=el.dataset.id;selectTab('runs');return}
if(a==='c-clear-run-filter'){maintenance.runFilter=null;render();return}
if(a==='c-open-run'){const r=maintenance.runs.find(r=>`${r.id}:${r.time}`===el.dataset.key);state.selected=r.id;state.head=r.head;state.reviewVersion=r.ruleVersion;state.reviewRule=r.ruleContent||defaultRule;state.model=r.model;state.effort=r.effort;state.writeback=r.writeback;state.outdated=false;state.incomplete=r.result==='证据不足';state.view='report';maintenance.editing=null;render();return}
if(a==='c-test-flow'){if(maintenance.editing)readFlowForm();maintenance.active=el.dataset.id;open('manual');return}
if(a==='c-edit-rule'){if(maintenance.editing)readFlowForm();maintenance.ruleEditing=el.dataset.id;close();openMaintenance('c-rule-editor');return}
if(a==='c-save-rule'){if(!readRule())return;close();render();notice('草稿已保存，正式规范版本不变。');return}
if(a==='c-publish-rule-confirm'){if(!readRule())return;openMaintenance('c-publish-rule');return}
if(a==='c-publish-rule'){finishRulePublish();return}
if(a==='c-sync-rule'){finishRulePublish();notice('已从 main 同步已发布规范（模拟）。');return}
if(a==='c-new-rule'){openMaintenance('c-new-rule');return}
if(a==='c-create-rule'){const d=new FormData($('#new-rule-form')),name=String(d.get('name')).trim(),text=String(d.get('content')).trim();if(!name||!text){$('#new-rule-error').textContent='请填写名称与规范内容。';return}const id='rule-'+Date.now();maintenance.rules.push({id,name,category:'通用规范',source:'steer',version:'0.0',content:'',draft:text,history:[]});maintenance.ruleEditing=id;close();openMaintenance('c-rule-editor');return}
},true);
document.addEventListener('input',e=>{if(e.target.id==='flow-search'){maintenance.search=e.target.value;saveMaintenance();const cursor=e.target.selectionStart;render();$('#flow-search').focus();$('#flow-search').setSelectionRange(cursor,cursor)}if(e.target.id==='rule-search'){maintenance.ruleSearch=e.target.value;saveMaintenance();const cursor=e.target.selectionStart;render();$('#rule-search').focus();$('#rule-search').setSelectionRange(cursor,cursor)}});
window.maintenancePrototype={get state(){return maintenance}};
const linkedFlow=new URLSearchParams(location.search).get('flow');
if(linkedFlow&&maintenance.flows.some(f=>f.id===linkedFlow)){maintenance.active=linkedFlow;maintenance.editing=linkedFlow;maintenance.flowDraft=clone(currentFlow().draft||currentFlow().published);state.view='home'}
render();

document.addEventListener('click',e=>document.querySelectorAll('details.native-menu[open]').forEach(menu=>{if(!menu.contains(e.target))menu.open=false}));
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('details.native-menu[open]').forEach(menu=>menu.open=false)});
